//! qk-serve-bf16 BS-5 — chat completions apply the MODEL'S OWN chat template,
//! rendered by `minijinja`, against a committed golden generated by the Python
//! HF stack with the same pinned kwargs.

#![allow(clippy::duplicate_mod)] // design D1: tests embed the binary's modules (no lib target)

#[path = "../src/api/mod.rs"]
pub mod api;
#[path = "../src/cli.rs"]
pub mod cli;
#[path = "../src/engine/mod.rs"]
pub mod engine;
#[path = "../src/model/mod.rs"]
pub mod model;
#[path = "../src/sampler.rs"]
pub mod sampler;

mod common;

use std::path::PathBuf;

use common::*;

fn golden_path() -> PathBuf {
    std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/chat_golden.json")
}

fn golden() -> serde_json::Value {
    let text = std::fs::read_to_string(golden_path()).expect("read chat_golden.json");
    serde_json::from_str(&text).expect("chat_golden.json is JSON")
}

fn golden_messages(golden: &serde_json::Value) -> Vec<api::types::ChatMessage> {
    serde_json::from_value(golden["messages"].clone()).expect("golden messages")
}

/// BS-5.1 — the fixture's canonical `chat_template.jinja` sidecar is the model's
/// own template, and the minijinja render of the pinned probing messages equals
/// BOTH the committed Python-HF render string AND its tokenization.
#[test]
fn chat_template_render_and_tokens_match_the_golden_bs_5_1() {
    let golden = golden();
    let loaded = model::load(&fixture_dir()).expect("fixture loads");
    let template = loaded
        .chat_template
        .clone()
        .expect("the fixture artifact declares a chat_template");

    let rendered =
        api::chat_template::render(&template, &golden_messages(&golden)).expect("render");
    assert_eq!(
        rendered,
        golden["prompt"].as_str().expect("golden prompt"),
        "BS-5.1: the minijinja render must equal the Python-HF golden string"
    );

    let ids: Vec<u32> = loaded
        .tokenizer
        .encode(rendered.as_str(), false)
        .expect("tokenize the rendered prompt")
        .get_ids()
        .to_vec();
    let want: Vec<u32> = golden["token_ids"]
        .as_array()
        .expect("golden token_ids")
        .iter()
        .map(|v| v.as_u64().expect("token id") as u32)
        .collect();
    assert_eq!(
        ids, want,
        "BS-5.1: the tokenized prompt ids must equal the Python-HF golden"
    );
}

/// BS-5.1 (blob leg) — a BLOB artifact carries the same sidecar as a raw
/// section, so the template and the golden hold for it too: a blob serves chat
/// exactly the way the directory does.
#[test]
fn blob_artifact_carries_the_same_chat_template_bs_5_1() {
    let golden = golden();
    let loaded = model::load(&blob_fixture()).expect("blob loads");
    let template = loaded
        .chat_template
        .clone()
        .expect("the blob artifact declares a chat_template");
    let rendered =
        api::chat_template::render(&template, &golden_messages(&golden)).expect("render");
    assert_eq!(rendered, golden["prompt"].as_str().expect("golden prompt"));
    // The two container forms of the same model resolve the SAME template
    // string, so they render identical prompts.
    let directory = model::load(&fixture_dir()).expect("directory loads");
    assert_eq!(
        directory.chat_template.as_deref(),
        Some(template.as_str()),
        "the blob and the directory must resolve the identical chat template"
    );
}

/// BS-5.2 — a message array the template cannot accept is a 400 in the error
/// envelope, and no generation is attempted.
#[test]
fn chat_template_failure_returns_400_bs_5_2() {
    for_each_serving_source(|artifact| {
        let (_state, router) = ready_router_for(artifact);
        let port = serve_on_port(router);
        for (label, body) in [
            (
                "empty messages",
                r#"{"model": "server-model-fixture", "messages": []}"#,
            ),
            (
                "unknown role",
                r#"{"model": "server-model-fixture", "messages": [{"role": "wizzard", "content": "hi"}]}"#,
            ),
        ] {
            let resp = post_json(port, "/v1/chat/completions", body).expect("request");
            assert_eq!(resp.status, 400, "{label}: {}", resp.body);
            let value: serde_json::Value = serde_json::from_str(&resp.body).expect("envelope JSON");
            assert_eq!(
                value["error"]["type"],
                serde_json::json!("invalid_request_error"),
                "{label}: the failure must ride the OpenAI envelope"
            );
            assert!(
                value["error"]["message"].is_string(),
                "{label}: the failure must name a reason"
            );
        }
    });
}

/// BS-5.1 (served leg) — the SERVED response's prompt-token count is the
/// template-rendered prompt's count, not the bare content join the pre-change
/// handler tokenized. That makes the template's application observable through
/// the API surface, not just through the module.
#[test]
fn served_chat_completion_tokenizes_the_templated_prompt_bs_5_1() {
    for_each_serving_source(|artifact| {
        let (state, router) = ready_router_for(artifact);
        let port = serve_on_port(router);
        let resp = post_json(
            port,
            "/v1/chat/completions",
            &chat_body(FIXTURE_MODEL_ID, false),
        )
        .expect("chat request");
        assert_eq!(resp.status, 200, "{}: {}", artifact.display(), resp.body);

        let template = state.engine.chat_template.clone().expect("template");
        let messages = vec![api::types::ChatMessage {
            role: "user".into(),
            content: "ab".into(), // what `chat_body` sends
        }];
        let templated = api::chat_template::render(&template, &messages).expect("render");
        let templated_tokens = state.engine.encode(&templated).expect("tokenize").len() as u64;
        let joined_tokens = state.engine.encode("ab").expect("tokenize").len() as u64;
        assert_ne!(
            templated_tokens, joined_tokens,
            "the fixture must distinguish the templated prompt from the bare join"
        );

        let body: serde_json::Value = serde_json::from_str(&resp.body).expect("chat JSON");
        assert_eq!(
            body["usage"]["prompt_tokens"],
            serde_json::json!(templated_tokens),
            "the served prompt_tokens must be the TEMPLATE-rendered prompt's count"
        );
    });
}

/// CT-3.2 — the committed fixture reproduces the shape a real export has: the
/// template in the canonical sidecar, and no `chat_template` field in the
/// tokenizer document. This is the structural half of the regression the real
/// artifact leg covers — a fixture that puts the template where no export puts
/// it is a suite that cannot see the gap.
#[test]
fn fixture_reproduces_the_real_artifact_shape_ct_3_2() {
    let dir = fixture_dir();
    let sidecar_path = dir.join("chat_template.jinja");
    let sidecar = std::fs::read_to_string(&sidecar_path)
        .unwrap_or_else(|e| panic!("{}: {e}", sidecar_path.display()));
    assert!(
        !sidecar.trim().is_empty(),
        "the sidecar must carry the model's template"
    );

    let document: serde_json::Value = serde_json::from_slice(
        &std::fs::read(dir.join("tokenizer.json")).expect("read the fixture tokenizer document"),
    )
    .expect("the fixture tokenizer document is JSON");
    assert!(
        document.get("chat_template").is_none(),
        "a real export's tokenizer.json carries no chat_template field"
    );

    let loaded = model::load(&dir).expect("the fixture loads");
    assert_eq!(
        loaded.chat_template.as_deref(),
        Some(sidecar.as_str()),
        "the loader must resolve the fixture's own sidecar bytes"
    );
}
